import "fmt"

// T and U are type parameters; U is independent of T.
func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s))
	for i, v := range s {
		out[i] = f(v)
	}
	return out
}

func main() {
	fmt.Println(Map([]int{1, 2, 3}, func(n int) int { return n * n }))
	// Output: [1 4 9]
}

