package solution

// Ordered admits any type whose underlying type supports < and >.
type Ordered interface {
	~int | ~int8 | ~int16 | ~int32 | ~int64 |
		~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 |
		~float32 | ~float64 | ~string
}

// MinMax returns the smallest and largest elements of xs.
// Empty slice -> zero values and ok=false.
func MinMax[T Ordered](xs []T) (min, max T, ok bool) {
	if len(xs) == 0 {
		return min, max, false // named results are already zero values
	}
	min, max = xs[0], xs[0] // seed with the first element
	for _, v := range xs[1:] {
		if v < min {
			min = v
		}
		if v > max {
			max = v
		}
	}
	return min, max, true
}

