func TestMinMax(t *testing.T) {
	lo, hi, ok := MinMax([]int{3, 1, 4, 1, 5, 9, 2})
	if !ok || lo != 1 || hi != 9 {
		t.Fatalf("ints: got (%d,%d,%v) want (1,9,true)", lo, hi, ok)
	}

	flo, fhi, ok := MinMax([]float64{2.5, -1.0, 3.3})
	if !ok || flo != -1.0 || fhi != 3.3 {
		t.Fatalf("floats: got (%v,%v,%v) want (-1,3.3,true)", flo, fhi, ok)
	}

	slo, shi, ok := MinMax([]string{"go", "rust", "c"})
	if !ok || slo != "c" || shi != "rust" {
		t.Fatalf("strings: got (%q,%q,%v) want (c,rust,true)", slo, shi, ok)
	}

	z, z2, ok := MinMax([]int{})
	if ok || z != 0 || z2 != 0 {
		t.Fatalf("empty: got (%d,%d,%v) want (0,0,false)", z, z2, ok)
	}
}

