package main

import "fmt"

type List[T any] struct {
	items []T
}

// A package-level function CAN declare both T and U.
func Map[T, U any](l List[T], f func(T) U) []U {
	out := make([]U, len(l.items))
	for i, v := range l.items {
		out[i] = f(v)
	}
	return out
}

func main() {
	l := List[int]{items: []int{1, 2, 3}}
	labels := Map(l, func(n int) string { return fmt.Sprintf("n%d", n) })
	fmt.Println(labels)
}

func Reduce[T, U any](s []T, init U, f func(acc U, x T) U) U {
	acc := init
	for _, v := range s {        // left fold
		acc = f(acc, v)          // caller supplies all type-specific logic
	}
	return acc
}

// Usage:
//   sum := Reduce([]int{1,2,3}, 0, func(a, x int) int { return a + x })      // 6
//   csv := Reduce([]string{"a","b"}, "", func(a, x string) string {
//       if a == "" { return x }
//       return a + "," + x
//   })                                                                        // "a,b"

package option

// Option holds a value that may be absent. The zero value is a valid None.
type Option[T any] struct {
	value   T
	present bool
}

// Some wraps a present value.
func Some[T any](v T) Option[T] { return Option[T]{value: v, present: true} }

// None returns an absent Option (same as the zero value).
func None[T any]() Option[T] { return Option[T]{} }

// IsSome reports whether a value is present.
func (o Option[T]) IsSome() bool { return o.present }

// Get returns the value and whether it was present (comma-ok style).
func (o Option[T]) Get() (T, bool) { return o.value, o.present }

// GetOr returns the value if present, otherwise the supplied default.
func (o Option[T]) GetOr(def T) T {
	if o.present {
		return o.value
	}
	return def
}

// Map transforms the wrapped value with f, preserving absence.
// It is a free function because U is a NEW type parameter and
// Go methods cannot declare their own type parameters.
func Map[T, U any](o Option[T], f func(T) U) Option[U] {
	if !o.present {
		return None[U]()
	}
	return Some(f(o.value))
}
